from sympy import jacobi_symbol, factorint
def red(D):
    out=0
    for a in range(1,isqrt(-D//3)+2):
        for b in range(-a,a+1):
            if (b*b-D)%(4*a): continue
            c=(b*b-D)//(4*a)
