            if b<0 and (-b==a or a==c): continue
            out+=1
    return out
def kron(D,n):
    r=1
    while n%2==0:
        n//=2
        if D%2==0: return 0
        r*= 1 if D%8 in (1,7) else -1
    return r*(jacobi_symbol(D%n,n) if n>1 else 1)
